{
  "county_id": "HVA04",
  "actions": [
    {
      "action_id": "self-sampling",
      "action": "Proposed: Mail a self-sampling kit with the second reminder to everyone who has not attended.",
      "rationale": "Cervical screening participation in Vantaa and Kerava wellbeing services county is 70.1% against the 80% target, and the portfolio selects self-sampling for this county with an expected gain of 1.5-4.5 percentage points.",
      "owner_role": "Accountable owner: Wellbeing services county screening unit.",
      "indicator": "Indicator to monitor: Proportion of women invited to cervical cancer screening (smear test) who attended, %.",
      "roadmap_measure": "2.4.4"
    },
    {
      "action_id": "screening-reminders",
      "action": "Proposed: Send a second kit with plain-language, multilingual instructions to non-responders; measure the gain as a stepped pilot.",
      "rationale": "Colorectal screening participation in Vantaa and Kerava wellbeing services county is 72.7% against the 80% target, and the portfolio selects screening-reminders for this county with an expected gain of 1.5-4.5 percentage points.",
      "owner_role": "Accountable owner: Wellbeing services county screening unit.",
      "indicator": "Indicator to monitor: Proportion of invited to colorectal cancer screening who attended, %.",
      "roadmap_measure": "1.3.1"
    },
    {
      "action_id": "pathway-timestamps",
      "action": "Proposed: Add first contact, referral, diagnosis and first treatment dates, plus entry route, to the national cancer quality register and publish county-level medians quarterly.",
      "rationale": "This is the first step recommended for every county, and Vantaa and Kerava cannot check the Goal 3 indicator on treatment within target times because time from referral to diagnosis and from diagnosis to first treatment is not published by county for any cancer.",
      "owner_role": "Accountable owner: FICAN with THL and the Finnish Cancer Registry.",
      "indicator": "Indicator to monitor: Share of new cancer cases with all four timestamps recorded.",
      "roadmap_measure": "3.2.1"
    }
  ],
  "evidence_does_not_support": "self-sampling: The Finnish gain over a reminder letter is about 3 points, far smaller than the international pooled estimate."
}

